package com.safebaba.service;
import com.safebaba.model.*; import com.safebaba.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class AgendaDisponibilidadeService {
 private final HorarioDisponibilidadeRepository hr; private final BloqueioAgendaRepository bl; private final BabaRepository br; private final AgendamentoRepository ar;
 public AgendaDisponibilidadeService(HorarioDisponibilidadeRepository hr,BloqueioAgendaRepository bl,BabaRepository br,AgendamentoRepository ar){this.hr=hr;this.bl=bl;this.br=br;this.ar=ar;}
 public List<HorarioDisponibilidade> horarios(Long id){return hr.findByBabaIdOrderByDiaSemanaAscHoraInicioAsc(id);}
 @Transactional public List<HorarioDisponibilidade> salvar(Long babaId,List<Slot> slots){ if(slots==null||slots.isEmpty())throw new IllegalArgumentException("Cadastre pelo menos um período semanal de atendimento."); Baba baba=br.findById(babaId).orElseThrow(); Set<String> chaves=new HashSet<>(); for(Slot s:slots){if(s.diaSemana()<1||s.diaSemana()>7||s.inicio()==null||s.fim()==null||!s.fim().isAfter(s.inicio()))throw new IllegalArgumentException("Revise os dias e horários informados."); String k=s.diaSemana()+"|"+s.inicio()+"|"+s.fim();if(!chaves.add(k))throw new IllegalArgumentException("Há horários duplicados.");}
 for(int i=0;i<slots.size();i++)for(int j=i+1;j<slots.size();j++){Slot a=slots.get(i),b=slots.get(j);if(a.diaSemana().equals(b.diaSemana())&&a.inicio().isBefore(b.fim())&&a.fim().isAfter(b.inicio()))throw new IllegalArgumentException("Os horários da mesma data não podem se sobrepor.");}
 hr.deleteByBabaId(babaId);List<HorarioDisponibilidade> out=new ArrayList<>();for(Slot s:slots){HorarioDisponibilidade h=new HorarioDisponibilidade();h.setBaba(baba);h.setDiaSemana(s.diaSemana());h.setHoraInicio(s.inicio());h.setHoraFim(s.fim());out.add(hr.save(h));}return out; }
 public List<BloqueioAgenda> bloqueios(Long babaId,LocalDate inicio,LocalDate fim){return bl.findByBabaIdAndInicioBetweenOrderByInicioAsc(babaId,inicio.atStartOfDay(),fim.plusDays(1).atStartOfDay());}
 @Transactional public BloqueioAgenda bloquear(Long babaId,LocalDateTime inicio,LocalDateTime fim,String motivo){if(inicio==null||fim==null||!fim.isAfter(inicio)||inicio.isBefore(LocalDateTime.now()))throw new IllegalArgumentException("Informe um período futuro válido para a folga.");Baba baba=br.findById(babaId).orElseThrow();for(LocalDate d=inicio.toLocalDate();!d.isAfter(fim.toLocalDate());d=d.plusDays(1)){for(Agendamento a:ar.findByBabaIdAndDataServicoAndStatusIn(babaId,d,List.of(StatusAgendamento.PENDENTE,StatusAgendamento.ACEITO))){LocalDateTime ai=d.atTime(a.getHoraInicio()),af=d.atTime(a.getHoraFim());if(inicio.isBefore(af)&&fim.isAfter(ai))throw new IllegalArgumentException("Já existe um atendimento solicitado ou confirmado nesse período.");}}if(!bl.findByBabaIdAndInicioLessThanAndFimGreaterThanOrderByInicioAsc(babaId,fim,inicio).isEmpty())throw new IllegalArgumentException("Já existe um bloqueio nesse período.");BloqueioAgenda b=new BloqueioAgenda();b.setBaba(baba);b.setInicio(inicio);b.setFim(fim);b.setMotivo(motivo);return bl.save(b);}
 @Transactional public void removerBloqueio(Long babaId,Long id){BloqueioAgenda b=bl.findByIdAndBabaId(id,babaId).orElseThrow(()->new IllegalArgumentException("Bloqueio não encontrado."));bl.delete(b);}
 public void validarAgendamento(Long babaId,LocalDate data,LocalTime inicio,LocalTime fim){LocalDateTime di=data.atTime(inicio),df=data.atTime(fim);if(!bl.findByBabaIdAndInicioLessThanAndFimGreaterThanOrderByInicioAsc(babaId,df,di).isEmpty())throw new IllegalArgumentException("A babá bloqueou esse período para folga. Escolha outro horário.");if(hr.existsByBabaId(babaId)){int dia=data.getDayOfWeek().getValue();boolean dentro=hr.findByBabaIdOrderByDiaSemanaAscHoraInicioAsc(babaId).stream().anyMatch(h->h.getDiaSemana()==dia&&!inicio.isBefore(h.getHoraInicio())&&!fim.isAfter(h.getHoraFim()));if(!dentro)throw new IllegalArgumentException("A babá não atende nesse dia ou horário. Consulte a agenda disponível.");}}
 public record Slot(Integer diaSemana,LocalTime inicio,LocalTime fim){}
}
